const same = (a:unknown,b:unknown) => JSON.stringify(a)===JSON.stringify(b);

/** Pure catalog inspection: no advisory gate, row DML or policy/material read.
 * Both owner-only tables or both precisely commissioned tables are accepted;
 * mixed ownership/grants, partial namespace, peer grants and drift are not. */
export async function inspectRoutinePaymentAccountPolicyCatalog(tx:Query,
  declaredNames?:RoutinePaymentAccountPolicyNames):Promise<RoutinePaymentAccountPolicyCatalog> {
  const names=declaredNames?{maintenance:declaredNames.maintenance,app:declaredNames.app,admin:declaredNames.admin}:undefined;
  if(names) {
    try { [names.maintenance,names.app,names.admin].forEach(pricingIdentifier);
      if(new Set(Object.values(names)).size!==3) throw Error('Distinct identities required'); }
    catch { return {present:true,ready:false,binding:null,failures:['binding']}; }
  }
  const [inventory]=await tx.execute<{present:boolean;namespace:boolean}>(sql`SELECT
    EXISTS(SELECT 1 FROM pg_catalog.pg_class WHERE relnamespace='public'::regnamespace AND
      (starts_with(relname,'routine_payment_account') OR starts_with(relname,'rpap_') OR starts_with(relname,'rpau_')))
    OR EXISTS(SELECT 1 FROM pg_catalog.pg_proc WHERE pronamespace='public'::regnamespace AND
      (starts_with(proname,'routine_payment_account') OR starts_with(proname,'rpap_') OR starts_with(proname,'rpau_')))
    OR EXISTS(SELECT 1 FROM pg_catalog.pg_type WHERE typnamespace='public'::regnamespace AND
      (starts_with(typname,'routine_payment_account') OR starts_with(typname,'_routine_payment_account')
      OR starts_with(typname,'rpap_') OR starts_with(typname,'_rpap_') OR starts_with(typname,'rpau_') OR starts_with(typname,'_rpau_')))
    OR EXISTS(SELECT 1 FROM pg_catalog.pg_constraint WHERE connamespace='public'::regnamespace AND
      (starts_with(conname,'routine_payment_account') OR starts_with(conname,'rpap_') OR starts_with(conname,'rpau_')))
    OR EXISTS(SELECT 1 FROM pg_catalog.pg_trigger WHERE starts_with(tgname,'routine_payment_account')
      OR starts_with(tgname,'rpap_') OR starts_with(tgname,'rpau_')) AS present,
    NOT EXISTS(SELECT 1 FROM pg_catalog.pg_class WHERE relnamespace='public'::regnamespace
      AND (starts_with(relname,'routine_payment_account') OR starts_with(relname,'rpap_') OR starts_with(relname,'rpau_'))
      AND relname NOT IN ('routine_payment_account_policy','routine_payment_account_use','rpap_pk','rpap_revision_uq','rpau_pk','rpau_evidence_idx'))
    AND (SELECT count(*)=1 FROM pg_catalog.pg_proc WHERE pronamespace='public'::regnamespace
      AND (starts_with(proname,'routine_payment_account') OR starts_with(proname,'rpap_') OR starts_with(proname,'rpau_')))
    AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_constraint WHERE connamespace='public'::regnamespace
      AND (starts_with(conname,'routine_payment_account') OR starts_with(conname,'rpap_') OR starts_with(conname,'rpau_'))
      AND conrelid IS DISTINCT FROM to_regclass('public.routine_payment_account_policy')
      AND conrelid IS DISTINCT FROM to_regclass('public.routine_payment_account_use'))
    AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_trigger WHERE
      (starts_with(tgname,'routine_payment_account') OR starts_with(tgname,'rpap_') OR starts_with(tgname,'rpau_'))
      AND tgrelid IS DISTINCT FROM to_regclass('public.routine_payment_account_policy')
      AND tgrelid IS DISTINCT FROM to_regclass('public.routine_payment_account_use')) AS namespace`);
  if(!inventory || typeof inventory.present!=='boolean') return {present:true,ready:false,binding:null,failures:['inventory']};
  if(!inventory.present) return {present:false,ready:false,binding:null,failures:[]};
  const failures:string[]=[];
  const check=(key:string,value:boolean)=>{if(!value)failures.push(key);};
  check('namespace',inventory.namespace===true);
  const bindings:Array<{maintenance:string;maintenanceOid:string;app:string|null;appOid:string|null}>=[];
  for(const spec of specs) {
    const [row]=await tx.execute<Record<string,unknown>>(sql`SELECT
      pg_catalog.pg_get_userbyid(c.relowner) AS maintenance,c.relowner::text AS maintenance_oid,
      current_setting('server_version_num')::integer/10000=16
      AND c.relkind='r' AND c.relpersistence='p' AND NOT c.relispartition AND NOT c.relrowsecurity AND NOT c.relforcerowsecurity
      AND c.relnatts=${spec.columns} AND c.relchecks=${spec.checks} AND c.reloptions IS NULL AND c.relreplident='d' AND c.reltablespace=0
      AND c.relam=(SELECT oid FROM pg_catalog.pg_am WHERE amname='heap')
      AND EXISTS(SELECT 1 FROM pg_catalog.pg_roles r WHERE r.oid=c.relowner AND r.rolsuper AND r.rolcanlogin
        AND (${names?.maintenance??null}::text IS NULL OR r.rolname=${names?.maintenance??null}::text))
      AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_inherits WHERE inhrelid=c.oid OR inhparent=c.oid)
      AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_rewrite WHERE ev_class=c.oid)
      AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_policy WHERE polrelid=c.oid)
      AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_constraint WHERE confrelid=c.oid)
      AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_constraint WHERE conrelid=c.oid AND contype NOT IN ('p','u','c','n'))
      AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_attribute WHERE attrelid=c.oid AND attnum>0
        AND (attisdropped OR atthasdef OR attidentity<>'' OR attgenerated<>'' OR attacl IS NOT NULL))
      AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_attrdef WHERE adrelid=c.oid)
      AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_depend WHERE classid='pg_catalog.pg_class'::regclass AND objid=c.oid AND deptype='e') AS safe,
      (SELECT jsonb_agg(jsonb_build_array(attnum,attname,format_type(atttypid,atttypmod),attnotnull,
        CASE WHEN attcollation=0 THEN NULL ELSE attcollation::regcollation::text END) ORDER BY attnum)
        FROM pg_catalog.pg_attribute WHERE attrelid=c.oid AND attnum>0) AS columns,
      (SELECT count(*)=${spec.constraints} AND bool_and(convalidated AND NOT condeferrable AND NOT condeferred
        AND conislocal AND coninhcount=0 AND conparentid=0 AND connamespace='public'::regnamespace)
        FROM pg_catalog.pg_constraint WHERE conrelid=c.oid AND contype IN ('p','u','c')) AS constraint_count,
      (SELECT jsonb_object_agg(conname,pg_get_constraintdef(oid,false)) FROM pg_catalog.pg_constraint
        WHERE conrelid=c.oid AND contype IN ('p','u','c')) AS constraints,
      (SELECT jsonb_object_agg(ic.relname,pg_get_indexdef(ic.oid)) FROM pg_catalog.pg_index i
        JOIN pg_catalog.pg_class ic ON ic.oid=i.indexrelid WHERE i.indrelid=c.oid) AS definitions,
      (SELECT count(*)=2 AND bool_and(i.indisvalid AND i.indisready AND i.indislive AND i.indimmediate
        AND NOT i.indisexclusion AND NOT i.indisclustered AND NOT i.indisreplident AND NOT i.indnullsnotdistinct
        AND i.indexprs IS NULL AND i.indpred IS NULL AND i.indnatts=i.indnkeyatts
        AND ic.relkind='i' AND ic.relpersistence='p' AND ic.reloptions IS NULL AND ic.reltablespace=0
        AND ic.relowner=c.relowner AND ic.relnamespace=c.relnamespace AND ic.relacl IS NULL
        AND ic.relam=(SELECT oid FROM pg_catalog.pg_am WHERE amname='btree') AND (${sql.raw(spec.indexShape)}))
        FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class ic ON ic.oid=i.indexrelid
        CROSS JOIN pg_catalog.pg_collation dc CROSS JOIN pg_catalog.pg_opclass op CROSS JOIN pg_catalog.pg_opclass ip CROSS JOIN pg_catalog.pg_opclass up
        WHERE i.indrelid=c.oid AND dc.collname='default' AND dc.collnamespace='pg_catalog'::regnamespace
          AND op.opcname='text_ops' AND op.opcnamespace='pg_catalog'::regnamespace
          AND op.opcmethod=(SELECT oid FROM pg_catalog.pg_am WHERE amname='btree')
          AND ip.opcname='int4_ops' AND ip.opcnamespace='pg_catalog'::regnamespace AND ip.opcmethod=op.opcmethod
          AND up.opcname='uuid_ops' AND up.opcnamespace='pg_catalog'::regnamespace AND up.opcmethod=op.opcmethod) AS indexes,
      (SELECT count(*)=2 AND bool_and(NOT t.tgisinternal AND t.tgenabled='O' AND t.tgnargs=0 AND t.tgqual IS NULL
        AND t.tgconstraint=0 AND t.tgfoid=f.oid AND t.tgattr::text='' AND t.tgoldtable IS NULL AND t.tgnewtable IS NULL
        AND ((t.tgname=${spec.prefix+'_immutable_rows'} AND t.tgtype=27)
          OR (t.tgname=${spec.prefix+'_immutable_truncate'} AND t.tgtype=34))) FROM pg_catalog.pg_trigger t WHERE t.tgrelid=c.oid) AS triggers,
      f.proowner=c.relowner AND f.prosrc=${ROUTINE_PAYMENT_ACCOUNT_POLICY_IMMUTABLE_BODY}
      AND f.prorettype='pg_catalog.trigger'::regtype AND f.pronargs=0 AND f.proargtypes::text=''
      AND NOT f.prosecdef AND NOT f.proleakproof AND f.provolatile='v' AND f.prokind='f'
      AND f.proconfig=ARRAY['search_path=pg_catalog'] AND NOT f.proisstrict AND NOT f.proretset AND f.proparallel='u'
      AND f.procost=100 AND f.prorows=0 AND f.prosupport=0 AND f.provariadic=0 AND f.pronargdefaults=0
      AND f.proargdefaults IS NULL AND f.proallargtypes IS NULL AND f.proargmodes IS NULL AND f.proargnames IS NULL
      AND f.probin IS NULL AND f.prosqlbody IS NULL AND f.protrftypes IS NULL
      AND f.prolang=(SELECT oid FROM pg_catalog.pg_language WHERE lanname='plpgsql' AND lanpltrusted)
      AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_trigger WHERE tgfoid=f.oid
        AND tgrelid IS DISTINCT FROM to_regclass('public.routine_payment_account_policy')
        AND tgrelid IS DISTINCT FROM to_regclass('public.routine_payment_account_use'))
      AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_depend WHERE classid='pg_catalog.pg_proc'::regclass AND objid=f.oid AND deptype='e')
      AND NOT EXISTS(SELECT 1 FROM pg_catalog.aclexplode(COALESCE(f.proacl,pg_catalog.acldefault('f',f.proowner))) a
        WHERE a.grantee<>f.proowner OR a.grantor<>f.proowner) AS function,
      NOT EXISTS(SELECT 1 FROM pg_catalog.aclexplode(COALESCE(c.relacl,pg_catalog.acldefault('r',c.relowner))) a
        LEFT JOIN pg_catalog.pg_roles r ON r.oid=a.grantee WHERE a.grantee<>c.relowner
        AND (a.grantee=0 OR a.grantor<>c.relowner OR a.is_grantable OR
          a.privilege_type NOT IN ${sql.raw(spec.insert?"('SELECT','INSERT')":"('SELECT')")}
          OR NOT r.rolcanlogin OR r.rolsuper OR r.rolcreatedb OR r.rolcreaterole OR r.rolinherit OR r.rolreplication OR r.rolbypassrls
          OR EXISTS(SELECT 1 FROM pg_catalog.pg_auth_members WHERE member=r.oid OR roleid=r.oid))) AS acl_safe,
      COALESCE((SELECT jsonb_agg(jsonb_build_array(r.rolname,r.oid::text,a.privilege_type,a.is_grantable)
        ORDER BY r.rolname COLLATE "C",a.privilege_type COLLATE "C")
        FROM pg_catalog.aclexplode(COALESCE(c.relacl,pg_catalog.acldefault('r',c.relowner))) a
        LEFT JOIN pg_catalog.pg_roles r ON r.oid=a.grantee WHERE a.grantee<>c.relowner),'[]'::jsonb) AS grants
      FROM pg_catalog.pg_class c JOIN pg_catalog.pg_proc f ON f.oid=to_regprocedure('public.routine_payment_account_immutable_v1()')
      WHERE c.oid=to_regclass(${`public.${spec.table}`})`);
    if(!row) { check(spec.table+':catalog',false); continue; }
    for(const key of ['safe','constraint_count','indexes','triggers','function','acl_safe']) check(spec.table+':'+key,row[key]===true);
    check(spec.table+':columns',same(row.columns,ROUTINE_PAYMENT_ACCOUNT_POLICY_EXPECTED_COLUMNS[spec.table]));
    const equalMap=(actual:unknown,expected:Record<string,string>)=>!!actual && typeof actual==='object'
      && Object.keys(actual).length===Object.keys(expected).length && Object.entries(expected).every(([key,value])=>(actual as Record<string,unknown>)[key]===value);
    check(spec.table+':constraints',equalMap(row.constraints,ROUTINE_PAYMENT_ACCOUNT_POLICY_EXPECTED_CONSTRAINTS[spec.table]));
    check(spec.table+':definitions',equalMap(row.definitions,spec.indexes));
    const allGrants=row.grants as Array<[string,string,string,boolean]>|null;
    const maintenance=typeof row.maintenance==='string'?row.maintenance:null,maintenanceOid=typeof row.maintenance_oid==='string'?row.maintenance_oid:null;
    const inserts=Array.isArray(allGrants)?allGrants.filter(g=>g[2]==='INSERT'):[];
    const hint=spec.insert?null:await routineRefundSourceAppCandidate(tx);
    const candidate=spec.insert?(inserts.length===1?inserts[0][0]:null):hint?.app??(allGrants?.length===1?allGrants[0][0]:null);
    const extras=Array.isArray(allGrants)?allGrants.filter(g=>g[0]!==candidate):[];
    const readers=extras.length&&maintenance&&candidate?await readRoutineRefundSourceReaders(tx,{maintenance,app:candidate}):[];
    if(extras.length)check(spec.table+':joint_readers',readers!==null&&readers.length>0);
    const grants=Array.isArray(allGrants)?allGrants.filter(g=>!readers?.includes(g[0])):null;
    let app:string|null=null,appOid:string|null=null;
    if(Array.isArray(grants) && grants.length===(spec.insert?2:1)
      && grants.every(g=>Array.isArray(g) && g.length===4 && g[0]===grants[0][0] && g[1]===grants[0][1] && !g[3])
      && grants.map(g=>g[2]).join(',')===(spec.insert?'INSERT,SELECT':'SELECT')) {app=grants[0][0];appOid=grants[0][1];}
    else check(spec.table+':acl',Array.isArray(grants) && grants.length===0);
    check(spec.table+':binding',maintenance!==null && maintenanceOid!==null && app!==maintenance
      && (!names || maintenance===names.maintenance && app===names.app));
    if(maintenance && maintenanceOid) bindings.push({maintenance,maintenanceOid,app,appOid});
  }
  check('joint_binding',bindings.length===2 && same(bindings[0],bindings[1]));
  const binding=bindings[0];
  if(!binding) return {present:true,ready:false,binding:null,failures:[...new Set(failures)].sort()};
  const {maintenanceOid,app}=binding;
  const [namespace]=await tx.execute<{safe:boolean;roles:boolean;admin_oid:string|null}>(sql`SELECT
    (SELECT count(*)=4 AND bool_and(t.typowner=${maintenanceOid}::oid AND t.typacl IS NULL AND
      ((t.typname IN ('routine_payment_account_policy','routine_payment_account_use') AND t.typtype='c'
        AND t.typrelid=to_regclass('public.'||t.typname) AND t.oid=(SELECT reltype FROM pg_catalog.pg_class WHERE oid=t.typrelid)
        AND t.typarray=to_regtype('public._'||t.typname))
      OR (t.typname IN ('_routine_payment_account_policy','_routine_payment_account_use') AND t.typtype='b'
        AND t.typelem=to_regtype('public.'||substr(t.typname,2)) AND t.oid=(SELECT typarray FROM pg_catalog.pg_type WHERE oid=t.typelem))))
      FROM pg_catalog.pg_type t WHERE t.typnamespace='public'::regnamespace
      AND (starts_with(t.typname,'routine_payment_account') OR starts_with(t.typname,'_routine_payment_account')
        OR starts_with(t.typname,'rpap_') OR starts_with(t.typname,'_rpap_') OR starts_with(t.typname,'rpau_') OR starts_with(t.typname,'_rpau_')))
    AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_default_acl d CROSS JOIN LATERAL pg_catalog.aclexplode(d.defaclacl) a
      WHERE (d.defaclrole=${maintenanceOid}::oid AND d.defaclnamespace IN (0,'public'::regnamespace)
        AND d.defaclobjtype IN ('r','f','S') AND a.grantee<>d.defaclrole)
      OR a.grantee IN (SELECT oid FROM pg_catalog.pg_roles WHERE rolname IN (${app},${names?.admin??null}))
      OR (a.grantee=0 AND d.defaclobjtype IN ('r','S'))) AS safe,
    (SELECT count(*)=${names?2:app?1:0} AND COALESCE(bool_and(r.rolcanlogin
      AND NOT(r.rolsuper OR r.rolcreatedb OR r.rolcreaterole OR r.rolinherit OR r.rolreplication OR r.rolbypassrls)
      AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_auth_members WHERE member=r.oid OR roleid=r.oid)
      AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_shdepend WHERE refclassid='pg_catalog.pg_authid'::regclass AND refobjid=r.oid AND deptype='o')
      AND pg_catalog.has_database_privilege(r.oid,current_database(),'CONNECT') AND pg_catalog.has_schema_privilege(r.oid,'public','USAGE')
      AND NOT pg_catalog.has_database_privilege(r.oid,current_database(),'CREATE')
      AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_namespace n WHERE n.nspname NOT LIKE 'pg_%' AND pg_catalog.has_schema_privilege(r.oid,n.oid,'CREATE'))
      AND NOT pg_catalog.has_parameter_privilege(r.oid,'session_replication_role','SET,ALTER SYSTEM')),true)
      FROM pg_catalog.pg_roles r WHERE r.rolname IN (${app},${names?.admin??null})) AS roles,
    (SELECT oid::text FROM pg_catalog.pg_roles WHERE rolname=${names?.admin??null}) AS admin_oid`);
  check('types_defaults',namespace?.safe===true);check('runtime_roles',namespace?.roles===true);
  const unique=[...new Set(failures)].sort();
  return {present:true,ready:unique.length===0,failures:unique,
    binding:unique.length===0?{...binding,admin:names?.admin??null,adminOid:namespace?.admin_oid??null}:null};
}

async function requireRuntime(tx:Query,allowAbsent:boolean,gate:boolean):Promise<boolean> {
  try {
    if(Object.hasOwn(tx,'$client')) throw Error('Caller-owned transaction required');
    await tx.execute(sql`SELECT
      set_config('statement_timeout',LEAST(NULLIF((SELECT setting::bigint FROM pg_catalog.pg_settings WHERE name='statement_timeout'),0),5000)::text||'ms',true),
      set_config('lock_timeout',LEAST(NULLIF((SELECT setting::bigint FROM pg_catalog.pg_settings WHERE name='lock_timeout'),0),1000)::text||'ms',true),
      set_config('idle_in_transaction_session_timeout',LEAST(NULLIF((SELECT setting::bigint FROM pg_catalog.pg_settings WHERE name='idle_in_transaction_session_timeout'),0),5000)::text||'ms',true)`);
    if(gate) {
      const [lock]=await tx.execute(sql`SELECT pg_try_advisory_xact_lock_shared(731717,0) AS locked`);
      if(lock?.locked!==true) throw Error('Account maintenance is busy');
    }
    const catalog=await inspectRoutinePaymentAccountPolicyCatalog(tx),binding=catalog.binding;
    if(allowAbsent && !catalog.present) return false;
    if(!catalog.ready || !binding?.app || !binding.appOid) throw Error('Account catalog is not ready');
    const [identity]=await tx.execute(sql`SELECT current_user=session_user AND current_user=${binding.app}::name
      AND r.oid=${binding.appOid}::oid AND (SELECT usesysid FROM pg_catalog.pg_stat_activity WHERE pid=pg_backend_pid())=r.oid
      AND current_setting('server_version_num')::integer/10000=16 AND current_setting('transaction_isolation')='read committed'
      AND current_setting('transaction_read_only')='off' AND current_setting('session_replication_role')='origin'
      AND current_schema()='public'
      AND to_regclass('routine_payment_account_policy')=to_regclass('public.routine_payment_account_policy')
      AND to_regclass('routine_payment_account_use')=to_regclass('public.routine_payment_account_use')
      AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_event_trigger WHERE evtenabled<>'D')
      AND r.rolcanlogin AND NOT(r.rolsuper OR r.rolcreatedb OR r.rolcreaterole OR r.rolinherit OR r.rolreplication OR r.rolbypassrls)
      AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_auth_members WHERE member=r.oid OR roleid=r.oid)
      AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_shdepend WHERE refclassid='pg_catalog.pg_authid'::regclass AND refobjid=r.oid AND deptype='o')
      AND pg_catalog.has_database_privilege(r.oid,current_database(),'CONNECT') AND pg_catalog.has_schema_privilege(r.oid,'public','USAGE')
      AND NOT pg_catalog.has_database_privilege(r.oid,current_database(),'CREATE')
      AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_namespace n WHERE n.nspname NOT LIKE 'pg_%' AND pg_catalog.has_schema_privilege(r.oid,n.oid,'CREATE'))
      AND NOT pg_catalog.has_parameter_privilege(r.oid,'session_replication_role','SET,ALTER SYSTEM')
      AND NOT pg_catalog.has_function_privilege(r.oid,to_regprocedure('public.routine_payment_account_immutable_v1()'),'EXECUTE') AS ready
      FROM pg_catalog.pg_roles r WHERE r.rolname=current_user`);
    if(identity?.ready!==true) throw Error('Unsafe actual runtime identity');
    return true;
  } catch { throw new ServiceUnavailableException('小程序付款账号策略或运行权限尚未就绪'); }
}
/** Fresh provider authorization only: acquire before physical/order locks. */
export async function assertRoutinePaymentAccountPolicyInstalledTx(tx:Query):Promise<boolean> {
  return requireRuntime(tx,true,true);
}
export async function assertRoutinePaymentAccountPolicyReady(tx:Query):Promise<void> {
  await requireRuntime(tx,false,true);
}
/** No advisory acquisition, no active/current policy read. Only for immutable
 * durable-use verification after an existing order lock, never fresh provider
 * authorization. Complete absence is false; partial/drift/wrong role is 503. */
export async function assertRoutinePaymentAccountPolicyReadInTx(tx:Query):Promise<boolean> {
  return requireRuntime(tx,true,false);
}

import { sql } from 'drizzle-orm';
import type { DbClient } from '@/lib/di';
import { ServiceUnavailableException } from '@/utils/errors';

/** Explicit maintenance definition, never request/startup DDL. These local
 * initiation and prepay records do not authorize historical payments/refunds.
 * Complete installer/runtime-role commissioning is still a separate gate. */
export const ROUTINE_PAYMENT_ATTEMPT_IMMUTABLE_BODY = `BEGIN
  RAISE EXCEPTION 'Routine payment attempts are immutable' USING ERRCODE='42501';
END`;
export const ROUTINE_PAYMENT_ATTEMPT_SQL = `
CREATE TABLE public.routine_payment_attempt (
  order_no varchar(32) NOT NULL,
  event_kind varchar(16) NOT NULL,
  payload jsonb NOT NULL,
  created_at bigint NOT NULL,
  signature varchar(64) NOT NULL,
  CONSTRAINT rpa_pk PRIMARY KEY(order_no,event_kind),
  CONSTRAINT rpa_order_ck CHECK(order_no ~ '^[A-Za-z0-9_-]{6,32}$'),
  CONSTRAINT rpa_kind_ck CHECK(event_kind IN ('INITIATION','PREPAY')),
  CONSTRAINT rpa_payload_ck CHECK(jsonb_typeof(payload)='object' AND octet_length(payload::text)<=16384),
  CONSTRAINT rpa_created_ck CHECK(created_at > 0),
  CONSTRAINT rpa_signature_ck CHECK(signature ~ '^[a-f0-9]{64}$')
);
CREATE FUNCTION public.routine_payment_attempt_immutable_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $rpa$${ROUTINE_PAYMENT_ATTEMPT_IMMUTABLE_BODY}$rpa$;
CREATE TRIGGER rpa_immutable_rows BEFORE UPDATE OR DELETE ON public.routine_payment_attempt
FOR EACH ROW EXECUTE FUNCTION public.routine_payment_attempt_immutable_v1();
CREATE TRIGGER rpa_immutable_truncate BEFORE TRUNCATE ON public.routine_payment_attempt
FOR EACH STATEMENT EXECUTE FUNCTION public.routine_payment_attempt_immutable_v1();
REVOKE ALL ON TABLE public.routine_payment_attempt FROM PUBLIC;
REVOKE ALL ON FUNCTION public.routine_payment_attempt_immutable_v1() FROM PUBLIC;
`;
const columns = [[1,'order_no','character varying(32)',true,'"default"'],[2,'event_kind','character varying(16)',true,'"default"'],
  [3,'payload','jsonb',true,null],[4,'created_at','bigint',true,null],[5,'signature','character varying(64)',true,'"default"']];
const constraints: Record<string,string> = {
  rpa_pk: 'PRIMARY KEY (order_no, event_kind)',
  rpa_order_ck: "CHECK (((order_no)::text ~ '^[A-Za-z0-9_-]{6,32}$'::text))",
  rpa_kind_ck: "CHECK (((event_kind)::text = ANY ((ARRAY['INITIATION'::character varying, 'PREPAY'::character varying])::text[])))",
  rpa_payload_ck: "CHECK (((jsonb_typeof(payload) = 'object'::text) AND (octet_length((payload)::text) <= 16384)))",
  rpa_created_ck: 'CHECK ((created_at > 0))',
  rpa_signature_ck: "CHECK (((signature)::text ~ '^[a-f0-9]{64}$'::text))",
};

/** Exact storage structure and limited S/I ACL inspection, not a claim that
 * the whole runtime role or the future author installer is commissioned. */
export async function inspectRoutinePaymentAttempt(tx: Pick<DbClient,'execute'>): Promise<boolean> {
  const [row] = await tx.execute(sql`SELECT
    c.relkind='r' AND c.relpersistence='p' AND NOT c.relispartition AND NOT c.relrowsecurity
    AND NOT c.relforcerowsecurity AND c.relnatts=5 AND c.relchecks=5 AND c.reloptions IS NULL
    AND c.relreplident='d' AND c.relam=(SELECT oid FROM pg_catalog.pg_am WHERE amname='heap')
    AND EXISTS(SELECT 1 FROM pg_catalog.pg_roles r WHERE r.oid=c.relowner AND r.rolsuper)
    AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_inherits WHERE inhrelid=c.oid OR inhparent=c.oid)
    AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_rewrite WHERE ev_class=c.oid)
    AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_attribute WHERE attrelid=c.oid AND attnum>0
      AND (attisdropped OR attgenerated<>'' OR attidentity<>'' OR atthasdef)) AS safe,
    (SELECT jsonb_agg(jsonb_build_array(a.attnum,a.attname,pg_catalog.format_type(a.atttypid,a.atttypmod),a.attnotnull,
      CASE WHEN a.attcollation=0 THEN NULL ELSE pg_catalog.to_jsonb(co.collname)::text END) ORDER BY a.attnum)
      FROM pg_catalog.pg_attribute a LEFT JOIN pg_catalog.pg_collation co ON co.oid=a.attcollation
      WHERE a.attrelid=c.oid AND a.attnum>0) AS columns,
    (SELECT jsonb_object_agg(conname,pg_catalog.pg_get_constraintdef(oid)) FROM pg_catalog.pg_constraint
      WHERE conrelid=c.oid AND convalidated AND NOT condeferrable AND NOT condeferred AND conislocal AND coninhcount=0) AS constraints,
    (SELECT count(*)=6 FROM pg_catalog.pg_constraint WHERE conrelid=c.oid) AS constraint_count,
    (SELECT count(*)=1 AND bool_and(i.indisvalid AND i.indisready AND i.indislive AND NOT i.indisclustered
      AND NOT i.indisreplident AND i.indpred IS NULL AND i.indexprs IS NULL AND i.indisprimary AND i.indisunique
      AND i.indkey::text='1 2' AND i.indoption::text='0 0' AND ic.relname='rpa_pk'
      AND ic.relkind='i' AND ic.relpersistence='p' AND ic.reloptions IS NULL AND ic.relowner=c.relowner
      AND ic.relam=(SELECT oid FROM pg_catalog.pg_am WHERE amname='btree'))
      FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class ic ON ic.oid=i.indexrelid WHERE i.indrelid=c.oid) AS indexes,
    (SELECT count(*)=2 AND bool_and(NOT t.tgisinternal AND t.tgenabled='O' AND t.tgnargs=0 AND t.tgqual IS NULL
      AND t.tgconstraint=0 AND t.tgfoid=f.oid AND t.tgattr::text='' AND t.tgoldtable IS NULL AND t.tgnewtable IS NULL
      AND ((t.tgname='rpa_immutable_rows' AND t.tgtype=27) OR (t.tgname='rpa_immutable_truncate' AND t.tgtype=34)))
      FROM pg_catalog.pg_trigger t WHERE t.tgrelid=c.oid) AS triggers,
    f.proowner=c.relowner AND f.prosrc=${ROUTINE_PAYMENT_ATTEMPT_IMMUTABLE_BODY} AND f.prorettype='pg_catalog.trigger'::regtype
    AND f.pronargs=0 AND f.proargtypes::text='' AND NOT f.prosecdef AND NOT f.proleakproof AND f.provolatile='v'
    AND f.prokind='f' AND f.proconfig=ARRAY['search_path=pg_catalog'] AND f.proparallel='u' AND f.prosupport=0
    AND NOT f.proisstrict AND NOT f.proretset AND f.provariadic=0 AND f.pronargdefaults=0 AND f.proargdefaults IS NULL
    AND f.proallargtypes IS NULL AND f.proargmodes IS NULL AND f.proargnames IS NULL AND f.probin IS NULL AND f.prosqlbody IS NULL
    AND f.prolang=(SELECT oid FROM pg_catalog.pg_language WHERE lanname='plpgsql')
    AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_proc p WHERE p.pronamespace=f.pronamespace AND p.proname=f.proname AND p.oid<>f.oid)
    AND NOT EXISTS(SELECT 1 FROM pg_catalog.aclexplode(COALESCE(f.proacl,pg_catalog.acldefault('f',f.proowner))) a WHERE a.grantee<>f.proowner) AS function,
    NOT EXISTS(SELECT 1 FROM pg_catalog.aclexplode(COALESCE(c.relacl,pg_catalog.acldefault('r',c.relowner))) a
      WHERE a.grantee<>c.relowner AND (a.grantee=0 OR a.is_grantable OR a.privilege_type NOT IN ('SELECT','INSERT')))
    AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_attribute col CROSS JOIN LATERAL pg_catalog.aclexplode(col.attacl) a
      WHERE col.attrelid=c.oid AND a.grantee<>c.relowner) AS acl
    FROM pg_catalog.pg_class c JOIN pg_catalog.pg_proc f ON f.oid=to_regprocedure('public.routine_payment_attempt_immutable_v1()')
    WHERE c.oid=to_regclass('public.routine_payment_attempt')`);
  if (!row || ['safe','constraint_count','indexes','triggers','function','acl'].some(key=>row[key]!==true)
    || JSON.stringify(row.columns)!==JSON.stringify(columns)) return false;
  const actual = row.constraints as Record<string,string> | undefined;
  return !!actual && Object.keys(actual).length===Object.keys(constraints).length
    && Object.entries(constraints).every(([key,value])=>actual[key]===value);
}

export async function assertRoutinePaymentAttemptReady(tx: Pick<DbClient,'execute'>): Promise<void> {
  if (Object.hasOwn(tx,'$client')) throw new ServiceUnavailableException('小程序付款记录需要调用方事务');
  const [gate]=await tx.execute(sql`SELECT pg_try_advisory_xact_lock_shared(731670,0) AS locked`);
  if (gate?.locked!==true || !await inspectRoutinePaymentAttempt(tx))
    throw new ServiceUnavailableException('小程序付款记录存储未完整就绪');
}

import { sql } from 'drizzle-orm';
import type { DbClient } from '../lib/di';
import { pricingIdentifier } from './checkoutPricingLockCatalog';
import { inspectRoutineIdentityWitness, ROUTINE_IDENTITY_WITNESS_SQL } from './routineIdentityWitness';
import { inspectRoutinePaymentAttempt, ROUTINE_PAYMENT_ATTEMPT_SQL } from './routinePaymentAttempt';
import { inspectLocalPaymentCaseLock, installLocalPaymentCaseLock } from './localPaymentCaseLock';

type Query = Pick<DbClient, 'execute'>;
export interface RoutinePaymentRuntimeNames {
  maintenance: string;
  app: string;
  admin: string;
  /** Explicit additional local-settlement LOGINs, never inferred from ACLs. */
  local?: readonly string[];
  /** Optional lock-only capability, bound to an explicit subset of local. */
  caseLock?: { owner: string; runtimeRoles: readonly string[] };
}
export interface RoutinePaymentRuntimeTarget extends RoutinePaymentRuntimeNames { database: string }
export const ROUTINE_PAYMENT_RUNTIME_OPERATION = 'routine-payment-storage-runtime-v1';
const TABLES = ['routine_identity_witness', 'routine_payment_attempt'] as const;

function roles(names: RoutinePaymentRuntimeNames) {
  const locals = names.local ?? [];
  if (!Array.isArray(locals) || locals.length > 16) throw Error('Explicit bounded local runtime identities required');
  const all = [names.maintenance, names.app, names.admin, ...locals];
  all.forEach(pricingIdentifier);
  if (new Set(all).size !== all.length) throw Error('Distinct routine runtime identities required');
  if (names.caseLock) {
    pricingIdentifier(names.caseLock.owner);
    const lockRoles = names.caseLock.runtimeRoles;
    if (!Array.isArray(lockRoles) || !lockRoles.length || lockRoles.length > 16 || all.includes(names.caseLock.owner)
      || new Set(lockRoles).size !== lockRoles.length || lockRoles.some(role => !locals.includes(role)))
      throw Error('Explicit local-only case lock binding required');
  }
  return [names.app, names.admin, ...locals].sort();
}

/** Addon grants only. Historical whole-shop/custom base plans retain their
 * meaning. App owns login observations and Mini initiation; Admin and declared
 * local principals only need immutable attempt presence and action evidence. */
export function routinePaymentRuntimeTablePrivileges(kind: 'app' | 'admin' | 'local') {
  if (!['app', 'admin', 'local'].includes(kind)) throw Error('Fixed routine runtime profile required');
  return {
    routine_identity_witness: kind === 'app' ? ['SELECT', 'INSERT'] as const : [],
    routine_payment_attempt: kind === 'app' ? ['SELECT', 'INSERT'] as const : ['SELECT'] as const,
  };
}

async function inspectRoles(tx: Query, names: RoutinePaymentRuntimeNames) {
  const expected = roles(names);
  const rows = await tx.execute(sql`SELECT r.rolname AS name,
    r.rolcanlogin AND NOT(r.rolsuper OR r.rolcreatedb OR r.rolcreaterole OR r.rolinherit OR r.rolreplication OR r.rolbypassrls)
    AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_auth_members WHERE member=r.oid OR roleid=r.oid)
    AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_shdepend WHERE refclassid='pg_catalog.pg_authid'::regclass AND refobjid=r.oid AND deptype='o')
    AND NOT pg_catalog.has_database_privilege(r.oid,current_database(),'CREATE')
    AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_namespace n WHERE n.nspname NOT LIKE 'pg_%'
      AND pg_catalog.has_schema_privilege(r.oid,n.oid,'CREATE'))
    AND NOT pg_catalog.has_parameter_privilege(r.oid,'session_replication_role','SET,ALTER SYSTEM')
    AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_default_acl d CROSS JOIN LATERAL pg_catalog.aclexplode(d.defaclacl) a
      WHERE a.grantee=r.oid OR (a.grantee=0 AND d.defaclobjtype IN('r','S'))) AS restricted
    FROM pg_catalog.pg_roles r WHERE r.rolname IN (${sql.join(expected.map(r => sql`${r}`), sql`, `)}) ORDER BY r.rolname`);
  return rows.length === expected.length && rows.every(r => r.restricted === true);
}

/** Exact owner/catalog/ACL comparison. No business rows, historical backfill,
 * repair, SET ROLE or grant inference. The caller supplies every allowed LOGIN.
 * This addon audit complements, and never replaces, the complete base audit. */
export async function inspectRoutinePaymentRuntime(tx: Query, names: RoutinePaymentRuntimeNames) {
  const runtimeRoles = roles(names), failures: string[] = [];
  const objects = await tx.execute(sql`SELECT 'relation' AS kind,c.relname AS name FROM pg_catalog.pg_class c
    WHERE c.relnamespace='public'::regnamespace AND (starts_with(c.relname,'routine_identity_witness')
      OR starts_with(c.relname,'routine_payment_attempt') OR starts_with(c.relname,'riw_') OR starts_with(c.relname,'rpa_'))
    UNION ALL SELECT 'function',p.proname FROM pg_catalog.pg_proc p WHERE p.pronamespace='public'::regnamespace
      AND (starts_with(p.proname,'routine_identity_witness') OR starts_with(p.proname,'routine_payment_attempt')
        OR starts_with(p.proname,'riw_') OR starts_with(p.proname,'rpa_'))`);
  const present = objects.length > 0;
  if (!present) return { present: false, storageReady: false, storageOnly: false, ledgerReady: false, ready: false, failures: [] as string[] };
  const expectedObjects = [
    'relation:routine_identity_witness', 'relation:riw_pk', 'relation:riw_binding_latest',
    'relation:routine_payment_attempt', 'relation:rpa_pk',
    'function:routine_identity_witness_immutable_v1', 'function:routine_payment_attempt_immutable_v1',
  ].sort();
  if (JSON.stringify(objects.map(r => `${r.kind}:${r.name}`).sort()) !== JSON.stringify(expectedObjects)) failures.push('namespace');
  const witness = await inspectRoutineIdentityWitness(tx), attempt = await inspectRoutinePaymentAttempt(tx);
  if (!witness) failures.push('witness_catalog');
  if (!attempt) failures.push('attempt_catalog');
  const [owner] = await tx.execute(sql`SELECT count(*)=2 AND bool_and(c.relowner=(SELECT oid FROM pg_catalog.pg_roles
    WHERE rolname=${names.maintenance} AND rolsuper)) AS exact FROM pg_catalog.pg_class c
    WHERE c.relnamespace='public'::regnamespace AND c.relname IN('routine_identity_witness','routine_payment_attempt')`);
  if (owner?.exact !== true) failures.push('maintenance_owner');
  const storageReady = failures.length === 0;
  const grants = await tx.execute(sql`SELECT c.relname AS name,a.privilege_type AS privilege,a.is_grantable AS delegate,
    CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(a.grantee) END AS role
    FROM pg_catalog.pg_class c CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(c.relacl,pg_catalog.acldefault('r',c.relowner))) a
    WHERE c.relnamespace='public'::regnamespace AND c.relname IN('routine_identity_witness','routine_payment_attempt') AND a.grantee<>c.relowner`);
  const expectedGrants: string[] = [];
  for (const role of runtimeRoles) {
    const plan = routinePaymentRuntimeTablePrivileges(role === names.app ? 'app' : role === names.admin ? 'admin' : 'local');
    for (const table of TABLES) for (const privilege of plan[table]) expectedGrants.push(`${table}:${role}:${privilege}`);
  }
  const actualGrants = grants.map(r => `${r.name}:${r.role}:${r.privilege}`).sort();
  const exactGrants = !grants.some(r => r.delegate !== false)
    && JSON.stringify(actualGrants) === JSON.stringify(expectedGrants.sort());
  const storageOnly = storageReady && grants.length === 0;
  if (!exactGrants) failures.push('ledger_acl');
  if (!await inspectRoles(tx, names)) failures.push('runtime_identities');
  const [action] = await tx.execute(sql`SELECT c.relkind='r' AND c.relpersistence='p' AND NOT c.relispartition
    AND NOT c.relrowsecurity AND NOT c.relforcerowsecurity
    AND c.relowner=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=${names.maintenance})
    AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_inherits WHERE inhrelid=c.oid OR inhparent=c.oid)
    AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_rewrite WHERE ev_class=c.oid) AS ordinary
    FROM pg_catalog.pg_class c WHERE c.oid=to_regclass('public.payment_reconciliation_action')`);
  if (action?.ordinary !== true) failures.push('action_catalog');
  if (action?.ordinary === true) {
    for (const role of runtimeRoles) {
      const [allowed] = await tx.execute(sql`SELECT pg_catalog.has_table_privilege(${role},'public.payment_reconciliation_action','SELECT')
        AND NOT pg_catalog.has_table_privilege(${role},'public.payment_reconciliation_action','SELECT WITH GRANT OPTION') AS ready`);
      if (allowed?.ready !== true) failures.push(`action_read:${role}`);
    }
  }
  const ledgerReady = failures.length === 0;
  const capability = await inspectLocalPaymentCaseLock(tx);
  if (!capability.absent || names.caseLock) {
    if (!names.caseLock || !capability.ready || capability.ownerName !== names.caseLock.owner
      || JSON.stringify(capability.grantees) !== JSON.stringify([...names.caseLock.runtimeRoles].sort())) failures.push('local_case_lock_binding');
    else for (const role of names.caseLock.runtimeRoles)
      if (!(await inspectLocalPaymentCaseLock(tx, role)).runtimeReady) failures.push(`local_case_lock_runtime:${role}`);
  }
  return { present, storageReady, storageOnly, ledgerReady, ready: failures.length === 0, failures: [...new Set(failures)].sort() };
}

async function setup(tx: Query, target: RoutinePaymentRuntimeTarget) {
  roles(target); pricingIdentifier(target.database);
  if (Object.hasOwn(tx, '$client')) throw Error('Routine installation requires a caller-owned maintenance transaction');
  await tx.execute(sql`SELECT set_config('search_path','public,pg_temp',true),
    set_config('statement_timeout',LEAST(NULLIF((SELECT setting::bigint FROM pg_catalog.pg_settings WHERE name='statement_timeout'),0),5000)::text||'ms',true),
    set_config('lock_timeout',LEAST(NULLIF((SELECT setting::bigint FROM pg_catalog.pg_settings WHERE name='lock_timeout'),0),1000)::text||'ms',true),
    set_config('idle_in_transaction_session_timeout',LEAST(NULLIF((SELECT setting::bigint FROM pg_catalog.pg_settings WHERE name='idle_in_transaction_session_timeout'),0),5000)::text||'ms',true)`);
  const [environment] = await tx.execute(sql`SELECT current_database()=${target.database} AND current_user=${target.maintenance}
    AND session_user=current_user AND current_setting('server_version_num')::integer/10000=16
    AND current_setting('transaction_isolation')='read committed' AND current_setting('transaction_read_only')='off'
    AND current_setting('session_replication_role')='origin'
    AND EXISTS(SELECT 1 FROM pg_catalog.pg_stat_activity a JOIN pg_catalog.pg_roles r ON r.oid=a.usesysid
      WHERE a.pid=pg_backend_pid() AND r.rolname=current_user AND r.rolsuper)
    AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_event_trigger WHERE evtenabled<>'D') AS ready`);
  if (environment?.ready !== true) throw Error('Routine maintenance target requires review');
  for (const gate of [731669, 731670]) {
    const [lock] = await tx.execute(sql`SELECT pg_try_advisory_xact_lock(${gate},0) AS locked`);
    if (lock?.locked !== true) throw Error('Routine storage maintenance is busy');
  }
}

/** Explicit absent-or-exact owner installation. Both ledgers and all addon
 * grants commit together. Partial namespaces/ACLs refuse; a replay validates
 * every catalog and grant without modifying data. No role creation or DDL is
 * reachable from request/startup. Existing users, orders and rows are retained. */
export async function installRoutinePaymentRuntimeInTransaction(tx: Query, target: RoutinePaymentRuntimeTarget) {
  await setup(tx, target);
  if (!await inspectRoles(tx, target)) throw Error('Routine runtime identities require review');
  let before = await inspectRoutinePaymentRuntime(tx, target);
  if (before.present && !before.storageReady) throw Error(`Routine storage preflight refused: ${before.failures.join(',')}`);
  if (before.present) {
    await tx.execute(sql.raw('LOCK TABLE ONLY public.routine_identity_witness, ONLY public.routine_payment_attempt IN ACCESS EXCLUSIVE MODE NOWAIT'));
    before = await inspectRoutinePaymentRuntime(tx, target);
    if (!before.storageReady) throw Error('Routine storage changed during maintenance locking');
    if (!before.ledgerReady && !before.storageOnly) throw Error('Routine addon partial grants require review');
  } else {
    await tx.execute(sql.raw(ROUTINE_IDENTITY_WITNESS_SQL));
    await tx.execute(sql.raw(ROUTINE_PAYMENT_ATTEMPT_SQL));
    const created = await inspectRoutinePaymentRuntime(tx, target);
    if (!created.storageOnly) throw Error('Routine storage creation verification refused');
  }
  if (!before.ledgerReady) {
    const [action] = await tx.execute(sql`SELECT c.relkind='r' AND c.relpersistence='p' AND NOT c.relispartition
      AND NOT c.relrowsecurity AND NOT c.relforcerowsecurity
      AND c.relowner=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=${target.maintenance}) AS ready
      FROM pg_catalog.pg_class c WHERE c.oid=to_regclass('public.payment_reconciliation_action')`);
    if (action?.ready !== true) throw Error('Routine action evidence table requires review');
    await tx.execute(sql.raw('LOCK TABLE ONLY public.payment_reconciliation_action IN SHARE MODE NOWAIT'));
    for (const role of roles(target)) {
      const name = pricingIdentifier(role), plan = routinePaymentRuntimeTablePrivileges(role === target.app ? 'app' : role === target.admin ? 'admin' : 'local');
      await tx.execute(sql.raw(`GRANT USAGE ON SCHEMA public TO ${name}`));
      for (const table of TABLES) if (plan[table].length)
        await tx.execute(sql.raw(`GRANT ${plan[table].join(',')} ON TABLE public.${table} TO ${name}`));
      await tx.execute(sql.raw(`GRANT SELECT ON TABLE public.payment_reconciliation_action TO ${name}`));
    }
  }
  const caseLock = target.caseLock ? await installLocalPaymentCaseLock(tx, { database: target.database,
    maintenance: target.maintenance, owner: target.caseLock.owner, runtimeRoles: target.caseLock.runtimeRoles }) : null;
  const after = await inspectRoutinePaymentRuntime(tx, target);
  if (!after.ready) throw Error(`Routine installation verification refused: ${after.failures.join(',')}`);
  return { operation: ROUTINE_PAYMENT_RUNTIME_OPERATION, applied: !before.ledgerReady || caseLock?.applied === true, before, after, caseLock,
    baseProfilesVerified: false as const, businessValidationRequired: true as const, historicalRowsReassigned: false as const };
}

export async function runRoutinePaymentRuntimeInstallation(db: DbClient, target: RoutinePaymentRuntimeTarget) {
  if (!Object.hasOwn(db, '$client')) throw Error('Root maintenance connection required');
  return db.transaction(tx => installRoutinePaymentRuntimeInTransaction(tx, target),
    { isolationLevel: 'read committed', accessMode: 'read write' });
}

/** Real LOGIN addon audit, read-only. A positive result is scoped to this
 * fixed storage delta; the separate complete base-role audit is still needed. */
export async function auditRoutinePaymentRuntime(db: DbClient, kind: 'app' | 'admin' | 'local', target: RoutinePaymentRuntimeTarget, localRole?: string) {
  if (!Object.hasOwn(db, '$client')) throw Error('Root runtime connection required');
  const expected = kind === 'local' ? localRole : target[kind];
  if (!expected || !roles(target).includes(expected) || (kind === 'local' && !target.local?.includes(expected))) throw Error('Explicit runtime audit identity required');
  return db.transaction(async tx => {
    await tx.execute(sql`SELECT set_config('statement_timeout','5000',true),set_config('lock_timeout','1000',true),
      set_config('idle_in_transaction_session_timeout','5000',true),set_config('search_path','public,pg_temp',true)`);
    const [identity] = await tx.execute(sql`SELECT current_database()=${target.database} AND current_user=${expected}
      AND session_user=current_user AND current_setting('server_version_num')::integer/10000=16
      AND current_setting('session_replication_role')='origin' AND EXISTS(SELECT 1 FROM pg_catalog.pg_stat_activity a
        JOIN pg_catalog.pg_roles r ON r.oid=a.usesysid WHERE a.pid=pg_backend_pid() AND r.rolname=${expected}) AS ready`);
    const state = await inspectRoutinePaymentRuntime(tx, target);
    return { ...state, ready: state.ready && identity?.ready === true, realLogin: identity?.ready === true,
      readOnly: true as const, baseProfilesVerified: false as const, kind };
  }, { isolationLevel: 'repeatable read', accessMode: 'read only' });
}

