      f.proowner=c.relowner AND f.prosrc=${ROUTINE_SHIPPING_IMMUTABLE_BODY}
      AND f.prorettype='pg_catalog.trigger'::regtype AND f.pronargs=0 AND f.proargtypes::text=''
