  if (!created.ready || created.binding?.app !== null) throw Error('Shipping initial owner-only catalog verification failed');
  await tx.execute(sql.raw(`GRANT SELECT ON TABLE public.routine_shipping_account_policy TO ${pricingIdentifier(target.app)}`));
  await tx.execute(sql.raw(`GRANT SELECT,INSERT ON TABLE public.routine_shipping_dispatch,public.routine_shipping_provider_evidence TO ${pricingIdentifier(target.app)}`));
  const after = await inspectRoutineShippingCatalog(tx, names);
  if (!after.ready) throw Error('Shipping installed catalog/ACL verification failed: ' + after.failures.join(','));
  const commissioned = await inspect();
  if (!commissioned.app.ready || !commissioned.admin.ready) throw Error('Shipping commissioned runtime profiles failed verification');
  return result(true);
}

